const { writeFileSync } = await import('node:fs');
const docBase64 = process.env.DOC_BASE64;
const docName = process.env.DOC_NAME;
if (!docBase64 || !docName) { throw new Error('Missing required input'); }
const filePath = `./${docName}`;
writeFileSync(filePath, Buffer.from(docBase64, 'base64'));
globalThis.inputPath = filePath;

const { readFile } = await import('node:fs');
const mod = await import('office-to-pdf');
const toPdf = mod.default || mod;
const buf = await readFile(globalThis.inputPath);
const pdfBuf = await toPdf(buf);
if (!pdfBuf || typeof pdfBuf.toString !== 'function') { throw new Error('Conversion did not return a Buffer'); }
globalThis.pdfBase64 = pdfBuf.toString('base64');
